import threading, time

lock = {1: threading.Lock(), 2: threading.Lock()}

def transfer(first, second, out, name):
    with lock[first]:                        # take the first row lock
        time.sleep(0.2)                      # simulate work, so the other thread interleaves
        ok = lock[second].acquire(timeout=1)     # wait for the second lock, with a timeout
        out[name] = ok
        if ok:
            lock[second].release()

def run(order_a, order_b):
    out = {}
    ts = [threading.Thread(target=transfer, args=(*order_a, out, "A")),
          threading.Thread(target=transfer, args=(*order_b, out, "B"))]
    for t in ts: t.start()
    for t in ts: t.join()
    return not all(out.values())             # True if somebody timed out

# A wants rows 1 then 2, B wants 2 then 1 -> a cycle of waits
print("opposite order, deadlock:", run((1, 2), (2, 1)))
# Both always lock the lower id first -> no cycle is possible
order = lambda x, y: tuple(sorted((x, y)))
print("sorted order,   deadlock:", run(order(1, 2), order(2, 1)))
